package app.repositories;

import app.common.Page;
import app.entities.Customer;
import java.math.BigDecimal;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;
import java.util.UUID;
import java.util.stream.Stream;
import org.bson.types.ObjectId;

/** Keeps customers rows in memory, for tests and for trying the services without a database. */
public class MemoryCustomerRepository implements CustomerRepository {
    private final Map<List<Object>, Customer> rows = new LinkedHashMap<>();

    /** The key of a row, as a list of its key values. */
    private static List<Object> keyOf(Customer row) {
        List<Object> key = new ArrayList<>();
        key.add(row.getId());
        return key;
    }

    /** Orders two keys value by value. */
    @SuppressWarnings({"unchecked", "rawtypes"})
    private static int compareKeys(List<Object> a, List<Object> b) {
        for (int index = 0; index < a.size(); index++) {
            int order = ((Comparable) a.get(index)).compareTo(b.get(index));
            if (order != 0) return order;
        }
        return 0;
    }

    private Stream<Customer> visible() {
        return rows.values().stream().filter((row) -> row.getDeletedAt() == null).sorted(Comparator.comparing(MemoryCustomerRepository::keyOf, MemoryCustomerRepository::compareKeys));
    }

    @Override
    public Optional<Customer> findById(String id) {
        return visible().filter((row) -> Objects.equals(row.getId(), id)).findFirst();
    }

    @Override
    public Page<Customer> list(int offset, int limit) {
        List<Customer> rows = visible().toList();
        return new Page<>(rows.stream().skip(offset).limit(limit).toList(), rows.size(), offset, limit);
    }

    @Override
    public Customer insert(Customer entity) {
        if (entity.getId() == null) entity.setId(new ObjectId().toHexString());
        rows.put(keyOf(entity), entity);
        return entity;
    }

    @Override
    public Customer update(Customer entity) {
        rows.put(keyOf(entity), entity);
        return entity;
    }

    @Override
    public void delete(Customer entity) {
        rows.remove(keyOf(entity));
    }

    @Override
    public Optional<Customer> addTag(String id, String tag) {
        Optional<Customer> found = visible().filter((row) -> Objects.equals(row.getId(), id)).findFirst();
        found.ifPresent((row) -> {
            List<String> items = row.getTags() == null ? new ArrayList<>() : new ArrayList<>(row.getTags());
            items.add(tag);
            row.setTags(items);
        });
        return found;
    }

    @Override
    public Optional<Customer> removeTag(String id, String tag) {
        Optional<Customer> found = visible().filter((row) -> Objects.equals(row.getId(), id)).findFirst();
        found.ifPresent((row) -> {
            List<String> items = row.getTags() == null ? new ArrayList<>() : new ArrayList<>(row.getTags());
            items.removeIf((item) -> Objects.equals(item, tag));
            row.setTags(items);
        });
        return found;
    }

    @Override
    public Optional<Customer> addEmpty(String id, Object empty) {
        Optional<Customer> found = visible().filter((row) -> Objects.equals(row.getId(), id)).findFirst();
        found.ifPresent((row) -> {
            List<Object> items = row.getEmpty() == null ? new ArrayList<>() : new ArrayList<>(row.getEmpty());
            items.add(empty);
            row.setEmpty(items);
        });
        return found;
    }

    @Override
    public Optional<Customer> removeEmpty(String id, int position, int size) {
        Optional<Customer> found = visible().filter((row) -> Objects.equals(row.getId(), id)).findFirst();
        if (found.isPresent() && (found.get().getEmpty() == null ? 0 : found.get().getEmpty().size()) != size) return Optional.empty();
        found.ifPresent((row) -> {
            List<Object> items = row.getEmpty() == null ? new ArrayList<>() : new ArrayList<>(row.getEmpty());
            items.remove(position);
            row.setEmpty(items);
        });
        return found;
    }
}

