package app.repositories;

import app.Documents;
import app.common.Page;
import app.entities.Order;
import com.mongodb.client.model.Filters;
import com.mongodb.client.model.FindOneAndUpdateOptions;
import com.mongodb.client.model.ReturnDocument;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.WeakHashMap;
import org.bson.Document;
import org.bson.types.ObjectId;
import org.springframework.dao.DataAccessException;
import org.springframework.data.domain.Sort;
import org.springframework.data.mongodb.core.MongoTemplate;
import org.springframework.data.mongodb.core.query.Criteria;
import org.springframework.data.mongodb.core.query.Query;

/** Keeps orders documents in the database, through a MongoTemplate. Every write is stored at once. */
public class MongoOrderRepository implements OrderRepository {
    /** The document each entity was read from: a change writes only the fields that differ */
    private static final Map<Order, Document> LOADED = Collections.synchronizedMap(new WeakHashMap<>());

    /** The fields a change may write */
    private static final List<String> FIELDS = List.of("number", "customer", "seller", "lines");

    private final MongoTemplate mongo;

    public MongoOrderRepository(MongoTemplate mongo) {
        this.mongo = mongo;
    }

    @Override
    public Optional<Order> findById(String id) {
        Order found = mongo.findOne(Query.query(Criteria.where("id").is(id)), Order.class);
        return Optional.ofNullable(found == null ? null : loaded(found));
    }

    @Override
    public Page<Order> list(int offset, int limit) {
        List<Order> items = mongo.find(new Query().with(Sort.by("id")).skip(offset).limit(limit), Order.class).stream().map(this::loaded).toList();
        return new Page<>(items, mongo.count(new Query(), Order.class), offset, limit);
    }

    @Override
    public List<Order> listByCustomer(String customer) {
        return mongo.find(Query.query(Criteria.where("customer").is(customer)).with(Sort.by("id")), Order.class).stream().map(this::loaded).toList();
    }

    @Override
    public Order insert(Order entity) {
        entity.identifyItems();
        try {
            mongo.insert(entity);
        } catch (DataAccessException error) {
            throw Documents.refusal("Order", error);
        }
        return loaded(entity);
    }

    @Override
    public Order update(Order entity) {
        entity.identifyItems();
        Document now = Documents.of(mongo, entity);
        Document changes = Documents.changes(LOADED.get(entity), now, FIELDS);
        try {
            if (!changes.isEmpty()) mongo.execute(Order.class, (collection) -> collection.updateOne(Filters.eq("_id", now.get("_id")), changes));
        } catch (DataAccessException error) {
            throw Documents.refusal("Order", error);
        }
        return loaded(entity);
    }

    @Override
    public void delete(Order entity) {
        try {
            mongo.remove(Query.query(Criteria.where("id").is(entity.getId())), Order.class);
        } catch (DataAccessException error) {
            throw Documents.refusal("Order", error);
        }
    }

    @Override
    public Optional<Order> addLine(String id, Order.Line line) {
        if (!ObjectId.isValid(id)) return Optional.empty();
        if (line.getId() == null) line.setId(new ObjectId().toHexString());
        Document change = new Document("$push", new Document("lines", Documents.of(mongo, line)));
        Document filter = new Document("_id", new ObjectId(id));
        FindOneAndUpdateOptions after = new FindOneAndUpdateOptions().returnDocument(ReturnDocument.AFTER);
        Document changed;
        try {
            changed = mongo.execute(Order.class, (collection) -> collection.findOneAndUpdate(filter, change, after));
        } catch (DataAccessException error) {
            throw Documents.refusal("Order", error);
        }
        return Optional.ofNullable(changed).map((document) -> loaded(mongo.getConverter().read(Order.class, document)));
    }

    @Override
    public Optional<Order> removeLine(String id, String lineId) {
        if (!ObjectId.isValid(id)) return Optional.empty();
        if (!ObjectId.isValid(lineId)) return Optional.empty();
        Document change = new Document("$pull", new Document("lines", new Document("_id", new ObjectId(lineId))));
        Document filter = new Document("_id", new ObjectId(id));
        FindOneAndUpdateOptions after = new FindOneAndUpdateOptions().returnDocument(ReturnDocument.AFTER);
        Document changed;
        try {
            changed = mongo.execute(Order.class, (collection) -> collection.findOneAndUpdate(filter, change, after));
        } catch (DataAccessException error) {
            throw Documents.refusal("Order", error);
        }
        return Optional.ofNullable(changed).map((document) -> loaded(mongo.getConverter().read(Order.class, document)));
    }

    /** The same entity, with what it is stored as kept to tell its changes. */
    private Order loaded(Order entity) {
        LOADED.put(entity, Documents.of(mongo, entity));
        return entity;
    }
}

