package app.services;

import app.UnitOfWork;
import app.common.Page;
import app.entities.Customer;
import app.errors.ConflictException;
import app.errors.FieldError;
import app.errors.NotFoundException;
import app.errors.ValidationFailedException;
import java.math.BigDecimal;
import java.time.Instant;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;

/** Operations on customers. Repositories commit every write. */
public class CustomerService {
    private final UnitOfWork uow;

    public CustomerService(UnitOfWork uow) {
        this.uow = uow;
    }

    /** Checks the values against the rules of the "customers" table, and the rows they point to; throws ValidationFailedException with every problem. */
    private void validate(UnitOfWork uow, Map<String, Object> values, Customer current) {
        boolean creating = current == null;
        List<FieldError> errors = new ArrayList<>();
        {
            Object value = values.get("email");
            if (value == null) {
                if (creating || values.containsKey("email")) errors.add(new FieldError("email", "is required"));
            }
        }
        {
            Object value = values.get("name");
            if (value == null) {
                if (creating || values.containsKey("name")) errors.add(new FieldError("name", "is required"));
            }
        }
        {
            Object value = values.get("rate");
            if (value == null) {
                if (creating || values.containsKey("rate")) errors.add(new FieldError("rate", "is required"));
            }
        }
        {
            Object value = values.get("active");
            if (value == null) {
                if (creating || values.containsKey("active")) errors.add(new FieldError("active", "is required"));
            }
        }
        {
            Object value = values.get("address");
            if (value == null) {
                if (creating || values.containsKey("address")) errors.add(new FieldError("address", "is required"));
            } else {
                Customer.Address document = (Customer.Address) value;
                if (document != null) checkAddress(document, "address", errors);
            }
        }
        {
            Object value = values.get("tags");
            if (value == null) {
                if (creating || values.containsKey("tags")) errors.add(new FieldError("tags", "is required"));
            }
        }
        if (!errors.isEmpty()) throw new ValidationFailedException("Customer", errors);
    }

    /** Every check before a write: the values, the rows they point to, the unique values. */
    private void check(UnitOfWork uow, Map<String, Object> values, Customer current) {
        validate(uow, values, current);
    }

    /** Sets the given values on the entity. */
    @SuppressWarnings("unchecked")
    private static void apply(Customer entity, Map<String, Object> values) {
        if (values.containsKey("email")) entity.setEmail((String) values.get("email"));
        if (values.containsKey("name")) entity.setName((String) values.get("name"));
        if (values.containsKey("age")) entity.setAge((Long) values.get("age"));
        if (values.containsKey("balance")) entity.setBalance((BigDecimal) values.get("balance"));
        if (values.containsKey("visits")) entity.setVisits((Long) values.get("visits"));
        if (values.containsKey("rate")) entity.setRate((Double) values.get("rate"));
        if (values.containsKey("active")) entity.setActive((Boolean) values.get("active"));
        if (values.containsKey("address")) entity.setAddress((Customer.Address) values.get("address"));
        if (values.containsKey("tags")) entity.setTags((List<String>) values.get("tags"));
        if (values.containsKey("seen")) entity.setSeen((Instant) values.get("seen"));
        if (values.containsKey("ref")) entity.setRef((UUID) values.get("ref"));
        if (values.containsKey("photo")) entity.setPhoto((byte[]) values.get("photo"));
        if (values.containsKey("scores")) entity.setScores((Object) values.get("scores"));
        if (values.containsKey("mixed")) entity.setMixed((Object) values.get("mixed"));
        if (values.containsKey("nothing")) entity.setNothing((Object) values.get("nothing"));
        if (values.containsKey("empty")) entity.setEmpty((List<Object>) values.get("empty"));
        if (values.containsKey("deletedAt")) entity.setDeletedAt((Instant) values.get("deletedAt"));
    }

    /** The Customer with this key; NotFoundException when there is none. */
    private Customer find(UnitOfWork uow, String id) {
        return uow.customers().findById(id).orElseThrow(() -> new NotFoundException("Customer", id));
    }

    /** The values an update gives, by field. */
    private static Map<String, Object> given(CustomerChanges changes) {
        Map<String, Object> values = new LinkedHashMap<>();
        if (changes.email() != null && changes.email().isPresent()) values.put("email", changes.email().value());
        if (changes.name() != null && changes.name().isPresent()) values.put("name", changes.name().value());
        if (changes.age() != null && changes.age().isPresent()) values.put("age", changes.age().value());
        if (changes.balance() != null && changes.balance().isPresent()) values.put("balance", changes.balance().value());
        if (changes.visits() != null && changes.visits().isPresent()) values.put("visits", changes.visits().value());
        if (changes.rate() != null && changes.rate().isPresent()) values.put("rate", changes.rate().value());
        if (changes.active() != null && changes.active().isPresent()) values.put("active", changes.active().value());
        if (changes.address() != null && changes.address().isPresent()) values.put("address", changes.address().value());
        if (changes.tags() != null && changes.tags().isPresent()) values.put("tags", changes.tags().value());
        if (changes.seen() != null && changes.seen().isPresent()) values.put("seen", changes.seen().value());
        if (changes.ref() != null && changes.ref().isPresent()) values.put("ref", changes.ref().value());
        if (changes.photo() != null && changes.photo().isPresent()) values.put("photo", changes.photo().value());
        if (changes.scores() != null && changes.scores().isPresent()) values.put("scores", changes.scores().value());
        if (changes.mixed() != null && changes.mixed().isPresent()) values.put("mixed", changes.mixed().value());
        if (changes.nothing() != null && changes.nothing().isPresent()) values.put("nothing", changes.nothing().value());
        if (changes.empty() != null && changes.empty().isPresent()) values.put("empty", changes.empty().value());
        if (changes.deletedAt() != null && changes.deletedAt().isPresent()) values.put("deletedAt", changes.deletedAt().value());
        return values;
    }

    /** What a Address does not follow of its rules, each with the path of its field. */
    private static void checkAddress(Customer.Address value, String path, List<FieldError> errors) {
        if (value.getStreet() == null) errors.add(new FieldError(path + ".street", "is required"));
        if (value.getCity() == null) errors.add(new FieldError(path + ".city", "is required"));
    }

    /** Stores a new Customer after checking it. */
    public Customer createCustomer(Customer customer) {
        Map<String, Object> values = new LinkedHashMap<>();
        if (customer.getEmail() != null) values.put("email", customer.getEmail());
        if (customer.getName() != null) values.put("name", customer.getName());
        if (customer.getAge() != null) values.put("age", customer.getAge());
        if (customer.getBalance() != null) values.put("balance", customer.getBalance());
        if (customer.getVisits() != null) values.put("visits", customer.getVisits());
        if (customer.getRate() != null) values.put("rate", customer.getRate());
        if (customer.getActive() != null) values.put("active", customer.getActive());
        if (customer.getAddress() != null) values.put("address", customer.getAddress());
        if (customer.getTags() != null) values.put("tags", customer.getTags());
        if (customer.getSeen() != null) values.put("seen", customer.getSeen());
        if (customer.getRef() != null) values.put("ref", customer.getRef());
        if (customer.getPhoto() != null) values.put("photo", customer.getPhoto());
        if (customer.getScores() != null) values.put("scores", customer.getScores());
        if (customer.getMixed() != null) values.put("mixed", customer.getMixed());
        if (customer.getNothing() != null) values.put("nothing", customer.getNothing());
        if (customer.getEmpty() != null) values.put("empty", customer.getEmpty());
        if (customer.getDeletedAt() != null) values.put("deletedAt", customer.getDeletedAt());
        return uow.transaction((uow) -> {
            check(uow, values, null);
            return uow.customers().insert(customer);
        });
    }

    /** The Customer with this key; NotFoundException when there is none. */
    public Customer getCustomer(String id) {
        return find(uow, id);
    }

    /** A page of customers, by primary key. */
    public Page<Customer> listCustomers(int offset, int limit) {
        return uow.customers().list(offset, limit);
    }

    /** Changes the given values of a Customer. */
    public Customer updateCustomer(String id, CustomerChanges changes) {
        Map<String, Object> values = given(changes);
        return uow.transaction((uow) -> {
            Customer current = find(uow, id);
            check(uow, values, current);
            apply(current, values);
            return uow.customers().update(current);
        });
    }

    /** Marks a Customer as deleted (deletedAt); reads leave it out from then on. */
    public void deleteCustomer(String id) {
        uow.transaction((uow) -> {
            Customer current = find(uow, id);
            if (!uow.orders().listByCustomer(current.getId()).isEmpty()) throw new ConflictException("Customer", "rows of orders still point to it", List.of("orders"));
            current.setDeletedAt(Instant.now());
            uow.customers().update(current);
            return null;
        });
    }

    /** Adds an item to tags. */
    public Customer addTag(String id, String tag) {
        return uow.transaction((uow) -> {
            find(uow, id);
            return uow.customers().addTag(id, tag).orElseThrow(() -> new NotFoundException("Customer", id));
        });
    }

    /** Removes an item from tags, by its value. */
    public Customer removeTag(String id, String tag) {
        return uow.transaction((uow) -> {
            Customer current = find(uow, id);
            if (current.getTags() == null || !current.getTags().contains(tag)) throw new NotFoundException("Tag", tag);
            return uow.customers().removeTag(id, tag).orElseThrow(() -> new NotFoundException("Customer", id));
        });
    }

    /** Adds an item to empty. */
    public Customer addEmpty(String id, Object empty) {
        return uow.transaction((uow) -> {
            find(uow, id);
            return uow.customers().addEmpty(id, empty).orElseThrow(() -> new NotFoundException("Customer", id));
        });
    }

    /** Removes an item from empty, by its position. */
    public Customer removeEmpty(String id, int position) {
        return uow.transaction((uow) -> {
            Customer current = find(uow, id);
            if (current.getEmpty() == null || position < 0 || position >= current.getEmpty().size()) throw new NotFoundException("Empty", position);
            return uow.customers().removeEmpty(id, position, current.getEmpty().size()).orElseThrow(() -> new ConflictException("Customer", "was changed by someone else since it was read", List.of("empty")));
        });
    }
}

