        if (changes.seller() != null && changes.seller().isPresent()) values.put("seller", changes.seller().value());
        if (changes.lines() != null && changes.lines().isPresent()) values.put("lines", changes.lines().value());
        return values;
    }

    /** What a Line does not follow of its rules, each with the path of its field. */
